from machine import UART, Pin
import time
from neo6m import NEO6M

uart = UART({UART_ID}, baudrate=9600, tx=Pin({RX}), rx=Pin({TX}))
gps = NEO6M(uart)
while True:
    if gps.update():
        if gps.fix and gps.latitude is not None:
            print('LAT=%.4f LON=%.4f ALT=%.1fm' % (gps.latitude, gps.longitude, gps.altitude or 0))
        else:
            print('Waiting for fix...')
    time.sleep_ms(200)
